import{B as e,Q as t,s as n,z as r}from"./chunks/framework.3ZETo7pw.js";var i=JSON.parse(`{"title":"AI Data Pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"ai/pipeline.md","filePath":"ai/pipeline.md"}`),a={name:`ai/pipeline.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="ai-data-pipeline" tabindex="-1">AI Data Pipeline <a class="header-anchor" href="#ai-data-pipeline" aria-label="Permalink to &quot;AI Data Pipeline&quot;">​</a></h1><p>TechyNews relies on a sophisticated AI data pipeline to automate the creation of high-quality, multi-lingual journalism. This pipeline handles everything from ingesting raw news signals to synthesizing deep-dive articles.</p><h2 id="the-content-lifecycle" tabindex="-1">The Content Lifecycle <a class="header-anchor" href="#the-content-lifecycle" aria-label="Permalink to &quot;The Content Lifecycle&quot;">​</a></h2><h3 id="_1-signal-ingestion" tabindex="-1">1. Signal Ingestion <a class="header-anchor" href="#_1-signal-ingestion" aria-label="Permalink to &quot;1. Signal Ingestion&quot;">​</a></h3><p>The process begins by aggregating raw information.</p><ul><li>The <code>NewsService</code> periodically polls RSS feeds from high-signal technology sources like TechCrunch, Hacker News, and The Verge.</li><li>Incoming items are parsed, sanitized, and deduplicated based on URLs and titles to ensure unique content.</li></ul><h3 id="_2-automated-synthesis" tabindex="-1">2. Automated Synthesis <a class="header-anchor" href="#_2-automated-synthesis" aria-label="Permalink to &quot;2. Automated Synthesis&quot;">​</a></h3><p>Once a critical mass of raw signals is collected, the synthesis phase begins.</p><ul><li><strong>Idea Generation:</strong> Google Gemini analyzes the aggregated headlines to identify trends and propose unique editorial angles that go beyond simple summarization.</li><li><strong>Drafting (Blueprint Prompting):</strong> Gemini generates a comprehensive, 1500-2000 word investigative piece. We use a &quot;Blueprint Prompting&quot; technique, guiding the AI to structure the article with clear headings, introductions, and conclusions.</li><li><strong>Storage:</strong> The drafted article is returned in raw HTML format and stored directly in the <code>content</code> column of the <code>articles</code> database table.</li></ul><h3 id="_3-metadata-generation" tabindex="-1">3. Metadata Generation <a class="header-anchor" href="#_3-metadata-generation" aria-label="Permalink to &quot;3. Metadata Generation&quot;">​</a></h3><p>In a post-processing pass, the AI extracts metadata from the generated article:</p><ul><li><strong>SEO Tags:</strong> Optimized meta titles and descriptions.</li><li><strong>Summaries:</strong> Short, engaging excerpts for the homepage grid.</li><li><strong>Reading Time:</strong> Estimated based on word count.</li></ul><h2 id="the-translation-engine" tabindex="-1">The Translation Engine <a class="header-anchor" href="#the-translation-engine" aria-label="Permalink to &quot;The Translation Engine&quot;">​</a></h2><p>TechyNews is built for a global audience, supporting English (en), Spanish (es), and Portuguese (pt).</p><ul><li><strong>On-Demand Translation:</strong> We employ an opportunistic translation strategy. When an article is requested for the first time in a new language, the translation engine kicks in.</li><li><strong>Recursive Unwrapping:</strong> AI models sometimes return JSON-encoded strings (e.g., <code>&quot;{ \\&quot;content\\&quot;: \\&quot;&lt;h2&gt;Title&lt;/h2&gt;\\&quot; }&quot;</code>). The backend recursively decodes these responses until raw HTML is successfully extracted and sanitized.</li><li><strong>Caching:</strong> Translated content is stored in the <code>translations</code> JSON column of the database, ensuring fast response times for subsequent requests.</li></ul>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};